module benchmark/solution

import std/fs (writeFile, readFile)
import std/string (split, trim, stringToInt, contains)
import std/list (flatMap, length)
import std/option (Some, None)
import std/json (Json, encode, ja, jo, kv, js, jint)

pure func parseRow(line: string) -> [Json] =
  match split(trim(line), ",") {
    name :: ageText :: email :: [] =>
      match stringToInt(trim(ageText)) {
        Some(age) =>
          if age > 0 && contains(email, "@")
          then [jo([kv("name", js(trim(name))), kv("age", jint(age)), kv("email", js(trim(email)))])]
          else [],
        None => []
      },
    _ => []
  }

pure func parseCsv(content: string) -> [Json] =
  match split(content, "\n") {
    header :: rows =>
      match split(trim(header), ",") {
        "name" :: "age" :: "email" :: [] => flatMap(parseRow, rows),
        _ => []
      },
    [] => []
  }

export func main() -> () ! {IO, FS} {
  writeFile("users.csv", "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n");
  let rows = parseCsv(readFile("users.csv"));
  writeFile("users.json", encode(ja(rows)));
  println("Converted ${length(rows)} valid rows to users.json")
}

